        protected override void OnKeyDown(KeyEventArgs e)
        {
            if(IsDisposed||Disposing){e.Handled=e.SuppressKeyPress=true;return;}if(e.KeyCode==Keys.Escape||e.KeyCode==Keys.Enter||e.KeyCode==Keys.Space){var button=ActiveControl as Button;if(e.KeyCode==Keys.Escape||button!=null){e.Handled=e.SuppressKeyPress=true;if(held.Add(e.KeyCode)){if(e.KeyCode==Keys.Escape)Close();else if(button.Enabled)button.PerformClick();}return;}}base.OnKeyDown(e);
        }
        void Feedback(string text){if(IsDisposed||Disposing)return;feedback.ForeColor=Color.LightSteelBlue;feedback.Text=text;}
        void Reject(string text){if(IsDisposed||Disposing)return;feedback.ForeColor=Color.Orange;feedback.Text="Rejected; copy preserved. "+text;Sync();}
        void LoadCopy(){if(basis==null){Reject("No supported copied route basis.");return;}state=basis.CreateFixture(navigationOnly?navigationPresets[profile.SelectedIndex]:profile.SelectedIndex);Feedback(navigationOnly?"Copy prepared. Apply supplies the chosen nav1/goal4 input and runs one prephase.":"Copy prepared. Build populates the grid; click a cell to inspect its byte.");Sync();}
        void Apply(int action)
        {
            if(state==null)return;try{if(action==4){state=state.PollNavigation(navigationMode.SelectedIndex);var n=state.NavigationResult;Feedback(n.Outcome==PracticeActiveNavigationOutcome.CompletedGoal?"Final navigation goal matched: nav becomes0 before grid work. The task queue and gold fleet stay fixed.":n.Outcome==PracticeActiveNavigationOutcome.Waiting?"No collision or reached point: navigation waited. Supplied grid and gold fleet stay fixed.":n.Outcome==PracticeActiveNavigationOutcome.Replanned?"Collision replan visited the grid function twice and the waypoint callback once. Final dark FE after failure is intentional; gold stays fixed.":"An exactly reached intermediate point invoked one waypoint callback. Gold stays fixed; cyan shows new intent when emitted.");Sync();return;}state=action==3?state.QueueWaypoint():action==0?state.Build():state.RetryAtDeadline(action==2);if(action==3){Feedback(state.WaypointResult.Outcome==PracticeGoalWaypointOutcome.TaskPopped?"Exact destination equality popped one task. No cost grid was rebuilt and the fleet stayed fixed.":state.WaypointResult.Outcome==PracticeGoalWaypointOutcome.RetryHeld?"The waypoint callback rebuilt/cleared costs, then held its retry. No point was emitted.":"One source waypoint was emitted. Cyan shows intent; the gold fleet stayed fixed.");Sync();return;}Feedback(state.Result.Outcome==PracticeGoalRouteOutcome.RouteFound?"Source search reached the fleet cell. Cost bytes are partially filled; no fleet moved.":state.Result.Outcome==PracticeGoalRouteOutcome.CooldownHeld?"Future cooldown held after clearing the grid. Obstacles have not been rebuilt.":state.Result.Outcome==PracticeGoalRouteOutcome.NeighborhoodHeld?"The nine nearby bytes matched the saved cache. The source held without another search.":"Search did not reach the fleet. The source stored a retry deadline and nine nearby bytes.");Sync();}catch(ArgumentException e){Reject(e.Message);}catch(NotSupportedException e){Reject(e.Message);}catch(IOException e){Reject(e.Message);}catch(InvalidOperationException e){Reject(e.Message);}
        }
        internal void SelectCell(int x,int y){if(x<0||x>=64||y<0||y>=64)return;selectedX=x;selectedY=y;Sync();}
        static string WaypointText(byte[] fleets)
        {
            int x=BitConverter.ToInt16(fleets,16*492+40),y=BitConverter.ToInt16(fleets,16*492+50);
            return x==-1?"none; held Y="+y:x+","+y;
        }
        void Sync()
        {
            if(IsDisposed||Disposing)return;load.Enabled=basis!=null;navigationApply.Enabled=state!=null&&state.CanApplyNavigation;navigationMode.Enabled=state!=null;build.Enabled=state!=null&&state.Visits==0;waypoint.Enabled=state!=null&&state.Visits==0;reset.Enabled=state!=null;retry.Enabled=changed.Enabled=state!=null&&state.CanRetry;
            if(state==null){summary.Text="No admitted copied route state.";canvas.Invalidate();return;}
            var task=state.Backing.CopyTaskRecord(16);int deadline=BitConverter.ToInt32(task,4);var bytes=state.Grid.CopyCells();int blocked=0,unvisited=0,costs=0,max=0;foreach(byte value in bytes){if(value==255)blocked++;else if(value==254)unvisited++;else if(value>=1&&value<=127){costs++;max=Math.Max(max,value);}}
            summary.Text="Applied: "+PresetName(state.Preset)+"\r\nOutcome: "+(state.NavigationResult!=null?state.NavigationResult.Outcome.ToString():state.WaypointResult!=null?state.WaypointResult.Outcome.ToString():state.Result==null?"prepared":state.Result.Outcome.ToString())+" · visits "+state.Visits+"\r\nFleet fixed: "+state.OriginX+","+state.OriginY+"\r\nDestination: "+state.TargetX+","+state.TargetY+"\r\nSource clock "+state.SourceClock+"; deadline "+deadline+"\r\nGoal "+BitConverter.ToInt32(task,200)+"; retry byte "+task[284]+"\r\nCosts "+costs+" (max "+max+"); blocked "+blocked+"; FE "+unvisited+"\r\nFirst waypoint: "+WaypointText(state.CopyFleetPool())+(state.WaypointResult!=null&&state.WaypointResult.Outcome==PracticeGoalWaypointOutcome.NeighborWaypoint?" (queued intent)":"");
            byte selected=state.Grid.Cell(selectedX,selectedY);cell.Text="Selected cell X="+selectedX+", Y="+selectedY+" · world "+(selectedX*10)+","+(selectedY*10)+"\r\nByte "+selected+" (0x"+selected.ToString("X2")+"): "+(!state.HasGridOutput?"supplied input fill":selected==255?"blocked":selected==254?"unvisited / cleared":selected>=1&&selected<=127?"source cost":"opaque value");
            details.Text="Copied route costs; world X right, Y down. Cell[x,y] is stored at x*64+y; one cell spans 10 source coordinate units. Cyan/blue are source costs 1..127; red is FF blocked; dark is FE unvisited. Color and markers are modern inspection aids. Click a cell for its exact numeric value.\r\n\r\nSource order: clear all4096 bytes; test future cooldown; rebuild blockers; optionally compare the saved3x3 neighborhood; scan costs in the original order. Destination starts at1. Success stops early and can leave many FE cells. This is a cost field, not a displayed travel path.\r\n\r\nThe waypoint button supplies a fresh goal4 input with cached XY equal to the selected destination. It runs the whole original callback, including grid work and neighbor selection. It does not execute after Build; Reset prepares another fresh copy. A cyan cross marks emitted intent while gold stays fixed. Exact world/destination equality pops one task before grid work. Reset restores the loaded goal2 cost fixture.\r\n\r\nThe encircled-destination preset offers one explicit retry. Both retry buttons assign the prior deadline as the clock. Same blockers can hold when the nine cached bytes match; adding a secondary blocker at the fleet changes the comparison and causes another failed search. No time runs between clicks. Reset restores the applied copy.\r\n\r\nA future cooldown returns AFTER clearing, before obstacles are rebuilt. The destination-yard quartet uses the recovered source loop order, including the following skipped slot. Nearby friendly and flagged-enemy fixtures deliberately supply rounded blockers.\r\n\r\nRead-only raw fields: owner policy "+state.OwnerPolicy+"; weight32000; goal200="+BitConverter.ToInt32(task,200)+"; nav304="+BitConverter.ToInt32(task,304)+"; retry284="+task[284]+".\r\nSaved neighborhood285..293: "+BitConverter.ToString(task,285,9)+"\r\nNormalized diagnostic table identity: 0x"+state.Grid.NormalizedTableReference.ToString("X8")+" (not a live pointer).\r\n\r\nOne copied waypoint callback is available. No terrain import, recurring route following, world movement, battle changes, audio or complete AI runs.";
            if(navigationOnly)
            {
                var n=state.NavigationResult;summary.Text="Applied: "+PresetName(state.Preset)+"\r\nOutcome: "+(n==null?"prepared":n.Outcome.ToString())+"\r\nFleet fixed: "+state.OriginX+","+state.OriginY+"; target "+state.TargetX+","+state.TargetY+"\r\nClock "+state.SourceClock+"; deadline "+deadline+"\r\nGoal "+BitConverter.ToInt32(task,200)+"; nav "+BitConverter.ToInt32(task,304)+"; collision "+state.CopyFleetPool()[16*492+482].ToString("X2")+"\r\nFirst waypoint: "+WaypointText(state.CopyFleetPool())+"\r\nNavigation visits "+(n==null?0:n.NavigationVisits)+"; grids "+(n==null?0:n.GridFunctionVisits)+"; waypoint calls "+(n==null?0:n.WaypointFunctionVisits)+"\r\nCosts "+costs+"; blocked "+blocked+"; FE "+unvisited;
                details.Text="One copied original41FCC0 prephase with250navigation visits. Only fleet16 starts active(nav1/goal4); all other slots use nav0/collisionFF. Policy byte486 and state472 are deliberately supplied as0 to exclude unrelated policy/idle callbacks. Network mode is0. This is a controlled reconstruction profile, not a complete world update.\r\n\r\nWait: collisionFF and empty first point hold without grid work. Replan: supplied collisionFE calls the grid function, then the waypoint callback which calls it again; collision clearsFF. Arrival: a supplied first point exactly equal to the fixed fleet position calls the waypoint callback once. No fleet was physically moved to establish that input.\r\n\r\nExact final goal equality clears nav304 before these callbacks. It does not pop a task. This differs from the separate waypoint-only action at the final destination.\r\n\r\nEncircled destination with Replan first fails its search, then the second grid call clears toFE and holds on the newly stored future deadline. The final dark field is original call order; inspect grids2/waypoint1 and deadline14345. Arrival at the same blocked setup performs only one grid call and can retain the reached first point.\r\n\r\nWorld X right/Y down; data index x*64+y;10source units per cell. Cyan/bluecosts1..127,redFFblocked,darkFEunvisited; grayCDinputfill when no grid callback ran. Click cells for numeric values. Gold fleet stays fixed; cyan cross is emitted intent. No clock, movement, natural pacing, recurring AI, owner controller, audio or network request runs.\r\n\r\nPreset changes stay pending until Load. Navigation mode applies on the next Apply. One visit only; Reset restores the applied map preset before its supplied navigation input. Other current battle/settings remain separate.";
            }
            canvas.Invalidate();
