        sealed class GridCanvas : Control
        {
            readonly PracticeGoalRouteStudy owner;RectangleF plot;
            internal GridCanvas(PracticeGoalRouteStudy owner){this.owner=owner;DoubleBuffered=true;ResizeRedraw=true;}
            protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left&&plot.Contains(e.Location))owner.SelectCell((int)((e.X-plot.Left)*64/plot.Width),(int)((e.Y-plot.Top)*64/plot.Height));}
            protected override void OnPaint(PaintEventArgs e)
            {
                base.OnPaint(e);var state=owner.state;if(state==null)return;
                Point? waypoint=null;if(state.WaypointResult!=null&&(state.WaypointResult.Outcome==PracticeGoalWaypointOutcome.NeighborWaypoint||state.WaypointResult.Outcome==PracticeGoalWaypointOutcome.CachedWaypoint)){var f=state.CopyFleetPool();waypoint=new Point(BitConverter.ToInt16(f,16*492+40),BitConverter.ToInt16(f,16*492+50));}
                string legend=!state.HasGridOutput?(state.Visits==0?"Prepared grid uses supplied CD fill. Build to inspect source costs.":"Source returned before grid work; supplied CD fill was held."):"Cyan/blue 1..127 cost · red FF blocked · dark FE unvisited";
                plot=PracticeRouteGridDrawing.Paint(e.Graphics,ClientSize,owner.Font,new PracticeRouteGridView{Grid=state.Grid,HasOutput=state.HasGridOutput,Origin=new Point(state.OriginX,state.OriginY),Target=new Point(state.TargetX,state.TargetY),Waypoint=waypoint,SelectedX=owner.selectedX,SelectedY=owner.selectedY,Header="Recovered cost field · +X right, +Y down",Subheader="Gold fleet · green destination · white selected cell",Footer=legend+"\r\nNo fleet movement or running clock. Markers stay fixed."});
            }
